describe('Date Picker Functionality', () => {
  it('should select a valid date successfully', () => {
    cy.visit('https://demoqa.com/date-picker');
    cy.get('#datePickerMonthYearInput').type('07/21/2026');
    cy.get('#datePickerMonthYearInput').should('have.value', '07/21/2026');
  });
  it('should not change the input when an invalid date is entered', () => {
    cy.visit('https://demoqa.com/date-picker');
    cy.get('#datePickerMonthYearInput').type('invalid date');
    cy.get('#datePickerMonthYearInput').should('have.value', '07/21/2026');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Date Picker Functionality', () => {
  test('should select a valid date successfully', async ({ page }) => {
    await page.goto('https://demoqa.com/date-picker');
    await page.fill('#datePickerMonthYearInput', '07/21/2026');
    const value = await page.inputValue('#datePickerMonthYearInput');
    expect(value).toBe('07/21/2026');
  });
  test('should not change the input when an invalid date is entered', async ({ page }) => {
    await page.goto('https://demoqa.com/date-picker');
    await page.fill('#datePickerMonthYearInput', 'invalid date');
    const value = await page.inputValue('#datePickerMonthYearInput');
    expect(value).toBe('07/21/2026');
  });
});
